      + `<path d="${D.pad}" fill="#0f1014" stroke="${line}" stroke-width="2"/>`
      + (window.KIT_FLOATING ? dpadCross(2 * 328.5 - (M.face.X[0] + M.face.B[0]) / 2, M.face.X[1], 39, 12, on) : `<path d="${D.dwell}" fill="none" stroke="${detail}" stroke-width="2"/><path d="${D.fwell}" fill="none" stroke="${detail}" stroke-width="2"/>` + ['dup', 'ddown', 'dleft', 'dright'].map(n => shape(D[n], 'D' + n.slice(1))).join(''))
      + Object.entries(M.face).filter(([k]) => k !== 'r').map(([k, [x, y]]) => {
          const col = v(k) > 0.5 ? '#0B0F17' : { A: '#8FB4FF', B: '#FF6B6B', X: '#F59BD5', Y: '#4DD6B5' }[k];
          return `<circle cx="${x}" cy="${y}" r="${M.face.r}" ${lit(k)} stroke-width="2"/>${psGlyph(k, x, y, M.face.r * 0.47, col)}`;
        }).join('')
